script:
stage(1000, 600, "#fbfbf8");
title({
  hu: "Derékszögű háromszög forgatása az átfogója körül (Kettős kúp)",
  en: "Rotation of a right triangle around its hypotenuse (Double cone)"
});

param("a", {hu: "Befogó a", en: "Leg a"}, 1, 6, 3, 0.5, "cm");
param("b", {hu: "Befogó b", en: "Leg b"}, 1, 6, 4, 0.5, "cm");
param("speed", {hu: "Forgási sebesség", en: "Rotation speed"}, 0.2, 3, 1, 0.1, "1/s");
toggle("showSolid", {hu: "Forgástest kitöltése", en: "Fill solid body"}, true);

let angle = 0; // Forgási szög (rad) / Rotation angle
update((dt, t) => {
  angle += 2 * PI * P.speed * dt; // Szög integrálása / Integrate angle
});

draw(t => {
  const a = P.a;
  const b = P.b;

  // 1. Geometriai számítások / Geometric calculations
  const c = sqrt(a * a + b * b); // Átfogó (c) / Hypotenuse
  const r = (a * b) / c;         // Magasság az átfogóhoz = a forgástest közös alapkörének sugara (r)
  const p = (a * a) / c;         // Az 'a' befogó vetülete az átfogón (alapkör helyzete)

  // Kettős kúp adatai / Properties of the double cone
  // A test két kúpból áll, amelyek magassága p és q (ahol p + q = c)
  const V = (1 / 3) * PI * r * r * c; // Térfogat: V = 1/3 * π * r² * c
  const A = PI * r * (a + b);         // Felszín: a két kúp palástjának összege (π*r*a + π*r*b)

  // 2. 3D kamera beállítása / Setup 3D camera view
  view3d({
    x: 500,
    y: 320,
    scale: 35, // pixel / cm
    yaw: t * 0.2 + 0.8, // lassan forgó kamera / slowly rotating camera
    pitch: deg(22), // enyhe felső rálátás / slight elevated view
    dist: 800
  });

  begin3();

  // Forgástengely (átfogó) rajzolása / Draw axis of rotation (hypotenuse)
  const yAxisBot = -c / 2;
  const yAxisTop = c / 2;
  arrow3([0, yAxisBot - 1, 0], [0, yAxisTop + 1, 0], {stroke: C.gray, lw: 2});
  text3("Átfogó (Tengely) / Hypotenuse", [0, yAxisTop + 1.2, 0], {size: 13, color: C.gray, align: "center"});

  // 3. Forgástest (kettős kúp) rajzolása / Draw the double cone solid
  const nSeg = 32;
  const yBase = yAxisBot + p; // A közös alapkör magassága Y mentén
  const baseCirc = circle3([0, yBase, 0], "y", r, nSeg);
  const apexBot = [0, yAxisBot, 0];
  const apexTop = [0, yAxisTop, 0];

  if (P.showSolid) {
    // Alapkör és palást árnyalás / Base and surface shading
    for (let i = 0; i < nSeg; i++) {
      const nextI = (i + 1) % nSeg;
      // Alsó kúp palást elemek / Lower cone surface triangles
      face3([apexBot, baseCirc[i], baseCirc[nextI]], {fill: C.blue, alpha: 0.15, stroke: null});
      // Felső kúp palást elemek / Upper cone surface triangles
      face3([apexTop, baseCirc[i], baseCirc[nextI]], {fill: C.blue, alpha: 0.15, stroke: null});
    }
  }

  // Kontúrok / Contours
  path3(baseCirc, {stroke: C.blue, lw: 2}, true); // Közös alapkör kontúrja

  // Alkotók a vázlathoz / Generators
  for (let i = 0; i < nSeg; i += 8) {
    path3([apexBot, baseCirc[i]], {stroke: C.blue, alpha: 0.2, lw: 1});
    path3([apexTop, baseCirc[i]], {stroke: C.blue, alpha: 0.2, lw: 1});
  }

  // 4. A forgó derékszögű háromszög kirajzolása 3D-ben / Draw rotating right triangle
  const cosA = cos(angle);
  const sinA = sin(angle);

  // A háromszög 3 csúcsa a térben / 3 vertices of the triangle in 3D
  const p1 = [0, yAxisBot, 0];                     // alsó csúcs
  const p2 = [0, yAxisTop, 0];                     // felső csúcs
  const p3 = [r * cosA, yBase, r * sinA];          // derékszögű csúcs (körpályán mozog)

  // Háromszög lap és keret / Triangle face and border
  face3([p1, p3, p2], {fill: C.orange, alpha: 0.6, stroke: C.ink});
  path3([p1, p3, p2, p1], {stroke: C.ink, lw: 2.5}, true);

  end3();

  // 5. Adatok megjelenítése / Display readouts and plots
  show({hu: "Átfogó (c)", en: "Hypotenuse (c)"}, c, "cm", 2);
  show({hu: "Alapkör sugara (r = h_c)", en: "Base radius (r)"}, r, "cm", 2);
  show({hu: "Forgástest térfogata (V)", en: "Volume (V)"}, V, "cm³", 1);
  show({hu: "Forgástest felszíne (A)", en: "Surface area (A)"}, A, "cm²", 1);

  plot({hu: "Térfogat V", en: "Volume V"}, V, {unit: "cm³", color: C.blue});
});
